message.content:
{
  "definition_simple": "罪や過ちを行うこと。または、他人の権利や領域を侵害すること。",
  "definition_standard": "法律、規則、道徳などに反する行為を実行する。また、他人の身体や権利を不当に侵害する。",
  "pos": "他動詞・五段活用・サ行",
  "semantic_class": "action",
  "sentences": [
    {
      "sentence": "彼は罪を犯した。",
      "difficulty": "T1"
    },
    {
      "sentence": "彼女は法律を犯したとして逮捕された。",
      "difficulty": "T2"
    },
    {
      "sentence": "プライバシーを犯す行為は許されない。",
      "difficulty": "T2"
    },
    {
      "sentence": "この契約は明らかに規則を犯している。",
      "difficulty": "T3"
    },
    {
      "sentence": "彼は過ちを犯してから深く反省した。",
      "difficulty": "T3"
    },
    {
      "sentence": "古代ローマでは神殿を犯すことは重罪とされた。",
      "difficulty": "T4"
    },
    {
      "sentence": "倫理綱領に反する行為は信頼を犯すことになる。",
      "difficulty": "T4"
    },
    {
      "sentence": "領空を犯す航空機は即座に警告を受けた。",
      "difficulty": "T5"
    },
    {
      "sentence": "彼の証言は法廷の秩序を犯すものだった。",
      "difficulty": "T5"
    },
    {
      "sentence": "国際法を犯した行為には厳格な制裁が科される。",
      "difficulty": "T6"
    }
  ],
  "morphological_forms": [
    {
      "form": "犯した",
      "label": "過去形"
    },
    {
      "form": "犯さない",
      "label": "否定形"
    }
  ],
  "morphology_wrong_forms": [
    {
      "base_form": "犯した",
      "wrong_forms": [
        {
          "form": "犯したた",
          "explanation": "過去形「犯した」に不要な「た」が付加されており、文法的に誤りです。"
        },
        {
          "form": "犯すた",
          "explanation": "終止形「犯す」に「た」を直接付けた形で、五段動詞の過去形は「犯した」が正しいため誤り。"
        },
        {
          "form": "犯したった",
          "explanation": "「犯した」にさらに「った」を重ねた形で、日本語の動詞活用に存在しない。"
        }
      ]
    },
    {
      "base_form": "犯さない",
      "wrong_forms": [
        {
          "form": "犯しない",
          "explanation": "否定形は「犯さない」が正しく、サ行五段活用では未然形「犯さ」に「ない」が付く。「犯しない」は一段活用の間違い。"
        },
        {
          "form": "犯さないない",
          "explanation": "「ない」が二重になり、冗長な誤り。"
        },
        {
          "form": "犯さぬ",
          "explanation": "「犯さぬ」は文語的で現代語では通常使われず、学習者が誤って用いる可能性がある。"
        }
      ]
    }
  ],
  "primary_collocate": "罪を犯す",
  "collocation_distractors": [
    {
      "word": "約束",
      "explanation": "「約束を犯す」は不自然で、正しくは「約束を破る」を用いる。意味的に「違反」を含むが、「犯す」とは共起しない。"
    },
    {
      "word": "夢",
      "explanation": "「夢を犯す」という表現は存在せず、通常は「夢を見る」「夢を叶える」などが使われる。"
    },
    {
      "word": "時間",
      "explanation": "「時間を犯す」は誤りで、「時間を空ける」「時間を過ごす」などが適切。「犯す」には時間を対象とする用法がない。"
    }
  ],
  "collocation_wrong_collocate": {
    "word": "目的",
    "explanation": "「目的を犯す」は誤りで、正しくは「目的を達成する」「目的を果たす」など。動詞「犯す」は通常目的語に取らない。"
  },
  "cloze_distractors": [
    {
      "sentence": "彼は＿＿を犯した。",
      "blank": "罪",
      "distractors": [
        {
          "word": "盗む",
          "explanation": "「盗む」は動詞であり、名詞の空欄に入れると文法的に不適切。また意味も異なる。"
        },
        {
          "word": "破る",
          "explanation": "「破る」は他動詞だが「罪を破る」とは言わず、共起しない。「規則を破る」などに用いる。"
        },
        {
          "word": "作る",
          "explanation": "「作る」は「罪」と共起せず、意味が全く異なる。"
        }
      ]
    }
  ],
  "discrimination_wrong_sentences": [
    {
      "sentence": "彼は窓を犯した。",
      "reason": "目的語「窓」は物理的な物体であり、動詞「犯す」は抽象的な対象（罪・規則・権利など）に用いるため不適切。正しくは「割る」「壊す」など。"
    },
    {
      "sentence": "彼はスピーチを犯した。",
      "reason": "「スピーチ」は行為の内容であり、「犯す」の目的語にならない。「スピーチを失敗する」「スピーチを台無しにする」などが適切。"
    },
    {
      "sentence": "彼は肉を犯した。",
      "reason": "「肉」は食用の物質で、この動詞が取る目的語として意味をなさない。完全に無関係な誤用。"
    }
  ],
  "spot_incorrect": {
    "sentence": "彼は約束を犯した。",
    "error_description": "動詞「犯す」は「約束」には使えない。正しくは「約束を破る」を用いる。",
    "corrected_version": "彼は約束を破った。"
  },
  "word_family_forms": [
    {
      "form": "犯行",
      "pos": "名詞"
    },
    {
      "form": "犯人",
      "pos": "名詞"
    },
    {
      "form": "犯罪",
      "pos": "名詞"
    }
  ],
  "word_family_fake_forms": [
    {
      "form": "犯しめる",
      "explanation": "「犯す」に可能動詞の語尾「-める」を付けたように見えるが、正しい可能動詞は「犯せる」であり、「犯しめる」は存在しない。"
    },
    {
      "form": "犯さる",
      "explanation": "「犯す」に「-さる」を付けて可能動詞のように見せているが、正しくは「犯せる」。五段動詞の可能形は語幹＋「える」であり、この形はない。"
    },
    {
      "form": "犯しさ",
      "explanation": "「犯し」＋「さ」で名詞化したように見えるが、実際の名詞形は「犯し」自体が稀で、「犯しさ」という形は用いられない。"
    }
  ],
  "syn_ant_candidates": [
    {
      "word": "違反する",
      "type": "synonym",
      "explanation": "「法律や規則に違反する」という意味で、本義の「犯す」と近い。ただし「犯す」はより重い罪や侵害に使われることが多い。"
    },
    {
      "word": "侵す",
      "type": "synonym",
      "explanation": "「他人の領域や権利を侵す」という意味で、「犯す」とほぼ同義だが、より物理的侵入のニュアンスが強い。"
    },
    {
      "word": "守る",
      "type": "antonym",
      "explanation": "「規則や約束を守る」は「犯す」の正反対の行為。"
    },
    {
      "word": "順守する",
      "type": "antonym",
      "explanation": "「法律を順守する」は「法律を犯す」の反意語として適切。"
    }
  ],
  "particle_candidates": {
    "sentence": "彼は罪___犯した。",
    "candidates": [
      {
        "particle": "を",
        "is_correct": true,
        "explanation": "「罪を犯す」が正しい格助詞。他動詞「犯す」の目的語は「を」で示す。"
      },
      {
        "particle": "が",
        "is_correct": false,
        "explanation": "「が」は主格を示すため、目的語として誤り。「罪が犯した」では意味が通じない。"
      },
      {
        "particle": "に",
        "is_correct": false,
        "explanation": "「に」は方向や対象を表すが、この文では目的語関係にならず誤り。"
      },
      {
        "particle": "と",
        "is_correct": false,
        "explanation": "「と」は引用や並列に使われ、文法的に不適切。"
      }
    ]
  }
}
